  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SDf := fresh "SDf" in let ACf := fresh "ACf" in let SKf := fresh "SKf" in let XSf := fresh "XSf" in let HCf := fresh "HCf" in
    pose proof (pside2_transport _ _ mc _ _ _ _ SIDE MU WM FW) as SDf;
    pose proof (pside2_aconst _ _ _ _ _ SDf) as ACf; pose proof (pside2_stack0 _ _ _ _ _ SDf) as SKf;
    pose proof (pside2_statics2 _ _ _ _ _ SDf) as XSf;
    assert (HCf : AHttpCat mc _) by (eapply AHttpCat_transport; [exact HC| exact MUh| exact WMh| CATTAC | CATTAC])
  end.

